#pragma once

int shape_area(int width, int height);
int shape_perimeter(int width, int height);

#include "include/geometry/shape.h"

int total(int width, int height) {
    return shape_area(width, height) + shape_perimeter(width, height);
}

#include "../../include/geometry/shape.h"

int legacy_area(int width, int height) {
    return shape_area(height, width);
}

#include "../include/geometry/shape.h"

int shape_area(int width, int height) {
    return width * height;
}

int shape_perimeter(int width, int height) {
    return 2 * (width + height);
}
